def _make_research_output(branch: str, count: int = 2) -> ResearchOutput:
    """Helper: build a mock ResearchOutput for a given branch."""
    return ResearchOutput(
        findings=[
            ResearchFinding(
                content=f"Finding {i} from {branch}",
                source_kind=ResearchSourceKind(
                    {"doc": "doc", "kb": "kb", "web": "web"}[branch]
                ),
                source_id=f"{branch}:source_{i}",
                relevance_score=0.85,
                citation_tag=f"[{branch}:source_{i}]",
            )
            for i in range(count)
        ],
        synthesis=f"Synthesised findings from {branch} branch",
        branch=branch,
    )


