class TestDocRagNode:

    @pytest.mark.asyncio
    async def test_returns_findings_with_correct_branch(self, base_state):
        mock_output = _make_research_output("doc")
        mock_chunks = [
            {
                "document": "BRD section content",
                "metadata": {
                    "section_id": "sec_001",
                    "project_id": "proj_test_001",
                    "page": 1,
                    "kind": "BRD",
                },
            }
        ]

        with patch(
            "app.workflows.planning.researcher_subgraph.PlanningChromaAdapter"
        ) as MockAdapter, patch(
            "app.workflows.planning.researcher_subgraph._invoke_structured",
            new_callable=AsyncMock,
            return_value=mock_output,
        ):
            mock_adapter_instance = AsyncMock()
            mock_adapter_instance.query_documents = AsyncMock(return_value=mock_chunks)
            MockAdapter.return_value = mock_adapter_instance

            result = await doc_rag_node(base_state)

        assert len(result["research_findings"]) == 2
        assert result["doc_synthesis"] == "Synthesised findings from doc branch"
        # Verify project_id filter was passed to adapter
        mock_adapter_instance.query_documents.assert_called_once_with(
            query=base_state.planning_goal,
            project_id="proj_test_001",
            n_results=8,
        )

    @pytest.mark.asyncio
    async def test_branch_failure_is_non_fatal(self, base_state):
        """A ChromaDB error must not raise — return empty findings instead."""
        with patch(
            "app.workflows.planning.researcher_subgraph.PlanningChromaAdapter"
        ) as MockAdapter:
            mock_adapter_instance = AsyncMock()
            mock_adapter_instance.query_documents = AsyncMock(
                side_effect=ConnectionError("ChromaDB unreachable")
            )
            MockAdapter.return_value = mock_adapter_instance

            result = await doc_rag_node(base_state)

        assert result["research_findings"] == []
        assert "branch_errors" in result
        assert len(result["branch_errors"]) == 1

    @pytest.mark.asyncio
    async def test_empty_chunks_returns_graceful_message(self, base_state):
        with patch(
            "app.workflows.planning.researcher_subgraph.PlanningChromaAdapter"
        ) as MockAdapter:
            mock_adapter_instance = AsyncMock()
            mock_adapter_instance.query_documents = AsyncMock(return_value=[])
            MockAdapter.return_value = mock_adapter_instance

            result = await doc_rag_node(base_state)

        assert result["research_findings"] == []
        assert "no document chunks" in result["doc_synthesis"]


