class TestSynthesiseNode:

    @pytest.mark.asyncio
    async def test_synthesises_all_branches(self, base_state):
        state_with_syntheses = base_state.model_copy(update={
            "doc_synthesis": "Doc branch found: chunking strategies [doc:sec_1]",
            "kb_synthesis": "KB branch found: RAG pattern applies [kb:RAG]",
            "web_synthesis": "Web branch found: LangGraph parallel edges [web:https://...]",
            "research_findings": [
                ResearchFinding(
                    content="Finding 1",
                    source_kind=ResearchSourceKind.DOC,
                    source_id="doc:sec_1",
                    relevance_score=0.9,
                    citation_tag="[doc:sec_1]",
                )
            ],
        })

        mock_response = MagicMock()
        mock_response.content = (
            "Unified synthesis: use RAG [kb:RAG] for document retrieval [doc:sec_1]. "
            "LangGraph supports this natively [web:https://...]. "
            "Multi-agent orchestration adds resilience [llm]."
        )

        with patch(
            "app.workflows.planning.researcher_subgraph._get_llm"
        ) as mock_llm_factory:
            mock_llm = AsyncMock()
            mock_llm.ainvoke = AsyncMock(return_value=mock_response)
            mock_llm_factory.return_value = mock_llm

            result = await synthesise_node(state_with_syntheses)

        assert "Unified synthesis" in result["final_synthesis"]
        assert result["total_findings"] == 1

    @pytest.mark.asyncio
    async def test_all_branches_empty_returns_graceful_degraded(self, base_state):
        """If all branches failed, synthesise must not crash."""
        result = await synthesise_node(base_state)  # all synthesis strings empty
        assert "Research could not be completed" in result["final_synthesis"]
        assert result["total_findings"] == 0


