class TestResearcherSubgraphIntegration:

    @pytest.mark.asyncio
    async def test_operator_add_accumulates_all_three_branches(self, base_state):
        """
        Critical test: verify that operator.add actually merges findings
        from all three branches, not just the last one to write.
        Total findings must equal sum of all branch findings.
        """
        doc_output = _make_research_output("doc", count=3)
        kb_output = _make_research_output("kb", count=2)
        web_output = _make_research_output("web", count=2)

        mock_chunks = [
            {"document": "chunk", "metadata": {"section_id": "s1", "project_id": "proj_test_001", "page": 1, "kind": "BRD"}}
        ]
        mock_kb_chunks = [
            {"document": "kb chunk", "metadata": {"name": "RAG"}}
        ]
        mock_web_response = MagicMock()
        mock_web_response.content = "web search result text"

        call_count = {"n": 0}
        outputs = [doc_output, kb_output, web_output]

        async def _mock_structured(llm, schema, system, user, run_id, branch):
            out = outputs[call_count["n"] % 3]
            call_count["n"] += 1
            return out

        mock_synthesis_response = MagicMock()
        mock_synthesis_response.content = "Combined synthesis with all citations"

        with patch(
            "app.workflows.planning.researcher_subgraph.PlanningChromaAdapter"
        ) as MockAdapter, patch(
            "app.workflows.planning.researcher_subgraph._get_web_search_llm"
        ) as mock_web_llm_factory, patch(
            "app.workflows.planning.researcher_subgraph._invoke_structured",
            side_effect=_mock_structured,
        ), patch(
            "app.workflows.planning.researcher_subgraph._get_llm"
        ) as mock_llm_factory:
            # Wire adapter
            mock_adapter_instance = AsyncMock()
            mock_adapter_instance.query_documents = AsyncMock(return_value=mock_chunks)
            mock_adapter_instance.query_patterns = AsyncMock(return_value=mock_kb_chunks)
            MockAdapter.return_value = mock_adapter_instance

            # Wire web search
            mock_web_llm = AsyncMock()
            mock_web_llm.ainvoke = AsyncMock(return_value=mock_web_response)
            mock_web_llm_factory.return_value = mock_web_llm

            # Wire synthesis LLM
            mock_llm = AsyncMock()
            mock_llm.ainvoke = AsyncMock(return_value=mock_synthesis_response)
            mock_llm_factory.return_value = mock_llm

            # Run full subgraph
            subgraph = build_researcher_subgraph()
            result = await subgraph.ainvoke(base_state.model_dump())

        # operator.add should have accumulated 3 + 2 + 2 = 7 findings
        assert len(result["research_findings"]) == 7, (
            f"Expected 7 findings (3+2+2), got {len(result['research_findings'])}. "
            "operator.add reducer may not be wired correctly."
        )
        assert result["final_synthesis"] == "Combined synthesis with all citations"
